def investigate(context, acquire):
    def simulate(actions):
        committed = {}
        main_tx = False
        other_tx = False
        main_pending = {}
        other_pending = {}
        channel = 0
        for act in actions:
            op = act.get('op')
            conn = act.get('connection', 'main')
            if op == 'begin':
                if conn == 'main':
                    main_tx = True
                    main_pending = {}
                else:
                    other_tx = True
                    other_pending = {}
            elif op == 'commit':
                if conn == 'main':
                    for k, v in main_pending.items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                    main_tx = False
                    main_pending = {}
                else:
                    for k, v in other_pending.items():
                        if v is None:
                            committed.pop(k, None)
                        else:
                            committed[k] = v
                    other_tx = False
                    other_pending = {}
            elif op == 'rollback':
                if conn == 'main':
                    main_tx = False
                    main_pending = {}
                else:
                    other_tx = False
                    other_pending = {}
            elif op == 'put':
                key = act.get('key')
                val = act.get('value')
                if conn == 'main':
                    if main_tx:
                        if key not in main_pending and key not in committed:
                            main_pending[key] = val
                            channel = 1
                        else:
                            channel = 0
                    else:
                        if key not in committed:
                            committed[key] = val
                            channel = 1
                        else:
                            channel = 0
                else:
                    if other_tx:
                        if key not in other_pending and key not in committed:
                            other_pending[key] = val
                    else:
                        if key not in committed:
                            committed[key] = val
            elif op == 'update':
                key = act.get('key')
                val = act.get('value')
                if conn == 'main':
                    if main_tx:
                        if key in main_pending:
                            main_pending[key] = val
                            channel = 1
                        elif key in committed:
                            main_pending[key] = val
                            channel = 1
                        else:
                            channel = 0
                    else:
                        if key in committed:
                            committed[key] = val
                            channel = 1
                        else:
                            channel = 0
                else:
                    if other_tx:
                        if key in other_pending:
                            other_pending[key] = val
                        elif key in committed:
                            other_pending[key] = val
                    else:
                        if key in committed:
                            committed[key] = val
            elif op == 'delete':
                key = act.get('key')
                if conn == 'main':
                    if main_tx:
                        if key in main_pending:
                            del main_pending[key]
                            channel = 1
                        elif key in committed:
                            main_pending[key] = None
                            channel = 1
                        else:
                            channel = 0
                    else:
                        if key in committed:
                            del committed[key]
                            channel = 1
                        else:
                            channel = 0
                else:
                    if other_tx:
                        if key in other_pending:
                            del other_pending[key]
                        elif key in committed:
                            other_pending[key] = None
                    else:
                        if key in committed:
                            del committed[key]
        return channel, committed

    goal = context.get('goal')
    actions = context.get('actions', [])
    channel, committed = simulate(actions)
    if goal == 'channel':
        return {'value': channel, 'unresolved': False}
    elif goal == 'committed_count':
        return {'value': len(committed), 'unresolved': False}
    elif goal == 'committed_sum':
        return {'value': sum(committed.values()), 'unresolved': False}
    return {'value': None, 'unresolved': True}

